import numpy as np
from keras.src import backend
from keras.src.optimizers.sgd import SGD
from keras.src.optimizers import base_optimizer

counter = {'n': 0}
orig = base_optimizer.BaseOptimizer.add_variable_from_reference

def wrapped(self, *args, **kwargs):
    counter['n'] += 1
    return orig(self, *args, **kwargs)

base_optimizer.BaseOptimizer.add_variable_from_reference = wrapped

optimizer = SGD(learning_rate=0.1, momentum=0.5, nesterov=True, clipnorm=0.75)
variables = [
    backend.Variable(np.array([1.0, -1.0], dtype='float32'), name=f'v{i}')
    for i in range(7)
]
grads = [
    np.array([2.5 + 0.1 * i, -1.7 - 0.05 * i], dtype='float32')
    for i in range(7)
]
optimizer.apply(grads, variables)
print(counter['n'])
